// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Deploy a helper that always succeeds on call
        Passer helper = new Passer();
        bool ret = c.transfer(from, address(helper), _tos, v);
        assertTrue(ret);
    }
}

contract Passer {
    fallback() external payable { }
}
